(function(){"use strict";app.factory("bancoService",function(t){const n=t.get("mainService"),e="Contabilidad/Banco/",r={get:function(t){return n.getData("get",e+"?json="+JSON.stringify(t),null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let n=JSON.parse(t.payload)||[];return n}})},post:function(t){return n.getData("post",`${e}?json=${JSON.stringify(t)}`,null,!0)},put:function(t,r){return n.getData("put",`${e}${t}?json=${JSON.stringify(r)}`,null,!0)},delete:function(t){return n.getData("delete",e+t,null,!0)}};return r})})(window.angular);